def postfix_to_infix(expression: str) -> str:
    stack = []
    for ch in expression:
        if ch.isalnum():
            stack.append(ch)
        else:
            a = stack.pop()   # right operand
            b = stack.pop()   # left operand
            stack.append(f"({b}{ch}{a})")
    return stack[0]

