#include <bits/stdc++.h>
using namespace std;

string postToInfix(string exp) {
    stack<string> st;
    for (char ch : exp) {
        if (isalnum((unsigned char)ch)) st.push(string(1, ch));
        else {
            string a = st.top(); st.pop();
            string b = st.top(); st.pop();
            st.push("(" + b + ch + a + ")");
        }
    }
    return st.top();
}

